  "plans.title": "StockHaven प्लान के तुलना करल",
  "plans.intro": "एगो खाता, चाहे कवनो प्लान चुनीं — Business में पाँच गो बिजनेस तक शामिल बा। कीमत मासिक अमेरिकी डॉलर में बा, आ पात्र नया वेबसाइट ग्राहक के Essentials आ Business में एगो सात दिन के ट्रायल मिल सकत बा। मौजूदा Essentials सब्सक्रिप्शन के Business में अपग्रेड करे से ट्रायल फेर से शुरू ना होई भा दोसरा मुफ्त ट्रायल ना बने। वेबसाइट प्लान के कीमत लागू होखे वाला टैक्स से पहिले के बा, अगर कवनो होखे। सब्सक्रिप्शन के मंजूरी देवे से पहिले राउर सही चार्ज देखावल जाई।",
