  "plans.priceNote": "Essentials $14.99/महीना बा आ साथे लागू होखे वाला टैक्स, अगर कवनो होखे। Business $29.99/महीना बा आ साथे लागू होखे वाला टैक्स, अगर कवनो होखे। कवनो जरूरी टैक्स प्रदाता चेकआउट के दौरान तय होला आ भुगतान से पहिले अंतिम कुल में देखावे के चाहीं। ई तुलना पेज कवनो टैक्स कोट भा भुगतान मंजूरी नइखे।",
  "plans.mobilePriceNote": "मोबाइल-ओनली प्लान के $4.99/महीना ओकर अमेरिका आधार कीमत बा। App Store भा Google Play खरीदारी से पहिले असली स्थानीय सब्सक्रिप्शन कीमत आ कवनो लागू टैक्स देखावेला। ओकर उत्पाद, साइट आ स्टाफ सीमा लॉन्च पर तय होला, वेबसाइट स्तर से अलग।",
  "plans.planChangeNote": "वेबसाइट प्लान बदले के पुष्टि बिलिंग प्रदाता से होखे के चाहीं। नया कीमत, प्रभावी तारीख आ कवनो प्रोरेशन बदलाव के मंजूरी देवे से पहिले समझावल जाई। अपग्रेड से दोसरा सब्सक्रिप्शन ना बने के चाहीं।",
