  "import.subtitleStart": "तीन अलग स्प्रेडशीट काम, ताकि दाम के सुधार कबो स्टॉक के रसीद के रूप में ना आ जाये। सब कुछ खाली",
  "import.subtitleRest": " में ही जाला, आ ड्राई रन पास होखे से पहिले कुछ लिखल ना जाला।",
  "import.createBusinessFirst": "पहिले बिजनेस बनाईं — इंपोर्ट कइल प्रोडक्ट कवनो बिजनेस के होला।",
  "import.createBusinessFirstShort": "पहिले बिजनेस बनाईं।",
  "import.whatEachDoes": "हर काम का करेला",
  "import.createTitle": "नया प्रोडक्ट बनाईं",
  "import.createDesc": "अइसन पंक्ति जोड़ेला जवन कैटलॉग में अबहीं ना बा। पहिले से इस्तेमाल हो रहल डुप्लिकेट SKU आ बारकोड छोड़ दिहल जाला, आ शुरुआती स्टॉक रसीद के रूप में रउआ चुन्हल जगह पर जा सकेला।",
  "import.updateTitle": "मौजूद प्रोडक्ट अपडेट करीं",
  "import.updateDesc": "हर पंक्ति के SKU भा रिकॉर्ड ID से मिलावेला आ पुरान मान के बगल में प्रस्तावित नया मान देखावेला। खाली सेल सहेजल मान के अइसहीं छोड़ देला, जब तक रउआ खाली सेल के साफ करे के ना कहब, आ मात्रा के कबो छूवल ना जाला।",
  "import.receiveModeTitle": "स्टॉक प्राप्त करीं",
  "import.receiveModeDesc": "आ रहल मात्रा के एगो जगह पर जोड़ देला आ हर लाइन खातिर मूवमेंट खाता में रसीद लिख देला। हर बैच पर निशान लगावल जाला, ताकि एकही शीट दू बेर प्राप्त ना होखे।",
  "import.excelNote": "Excel वर्कबुक (.xlsx) सीधे पढ़ल जाला — वर्कशीट चुनीं आ कॉलम अपने आप मिल जाला। कोड पूरा रहेला: टेक्स्ट के रूप में सहेजल UPC आपन अंक आ आगे के शून्य बनवले रहेला। जवन पंक्ति इंपोर्ट ना हो सकेला ओकरा के कारण के साथ सूचीबद्ध कइल जाला",
  "import.excelNoteDownload": " आ फाइल के रूप में डाउनलोड कइल जा सकेला।",
  "import.excelNoteFix": ", ताकि रउआ ओकरा के ठीक क के फेर से कोशिश कर सकीं।",
