  "valuation.footnote": "लागत मूल्य में हर प्रोडक्ट के वर्तमान इकाई लागत इस्तेमाल होला, एही से नया दाम पर प्राप्त करे से पूरा अलमारी के फेर से मूल्यांकन हो जाला। रोकल इकाई अबहीं इहाँ गिनल जाला — ओह हाथ में बा, खाली कवनो ऑर्डर के वादा कइल गइल बा। गायब पैसा के कबो शून्य ना मानल जाला; आँकड़ा मालूम होखे तक फील्ड के खाली छोड़ीं।",
