  "staff.access.noSeatBody": "एह बिजनेस खातिर रउआ के खाता में कवनो स्टाफ सीट नइखे, एह से एकर स्टॉक बंद रहेला। मालिक से कहके Staff & roles में रउआ के जोड़े के कहाईं।",
  "staff.access.noSeatTitle": "ई बिजनेस रउआ के लॉगिन खातिर खुलल नइखे",
  "staff.access.pendingBody": "एह बिजनेस में रउआ के ईमेल खातिर एगो निमंत्रण बा, जवन अभी सक्रिय ना भइल बा। मालिक से कहके रउआ के स्टाफ स्थिति सक्रिय कराईं। ओह समय तक एहिजा कुछुओ ना देखाई।",
  "staff.access.pendingTitle": "रउआ के निमंत्रण अभी सक्रिय नइखे",
  "staff.access.signOut": "साइन आउट करीं",
  "staff.access.suspendedBody": "प्रशासक एह बिजनेस खातिर एह स्टाफ खाता के निलंबित कइले बा। ओह से कहके रउआ के फेर से सक्रिय कराईं, फेर साइन इन करीं।",
  "staff.access.suspendedTitle": "रउआ के पहुँच रुकल बा",
  "staff.addFirst": "पहिलका स्टाफ सदस्य जोड़ीं",
  "staff.addMember": "स्टाफ सदस्य जोड़ीं",
  "staff.emptyBody": "एगो आदमी जोड़ीं, ओकरा के एगो भूमिका आ ओकर साथे मिले वाला अनुमति दीं, आ ओकरा के ईमेल से एह बिजनेस में साइन इन करे के निमंत्रण भेजल जाई।",
  "staff.emptyTitle": "अभी कवनो स्टाफ नइखे",
  "staff.eyebrow": "टीम",
  "staff.how.p1": "हर सदस्य के एगो भूमिका आ अपना अनुमति के सूची रहेला, एह से रउआ भूमिका से शुरू करके नया भूमिका बनवले बिना एक चीज बदल सकेनीं। भूमिका बदले से ओह पर पहिले से मौजूद सदस्य ना बदलेनीं — ओह लोग के भूमिका के डिफ़ॉल्ट फेर से लागू करे खातिर सदस्य के खोलीं।",
  "staff.how.p2": "कस्टम भूमिका एगो Business सुविधा ह: Essentials में पाँच गो बनल-बनल भूमिका इस्तेमाल होला (मालिक, प्रबंधक, स्टॉक क्लर्क, बिक्री क्लर्क, दर्शक)।",
  "staff.how.p3": "निमंत्रण ईमेल से भेजल जाला। सदस्य तभी साइन इन कर सकेला जब ऊ स्वीकार कर लेई, आ एह सूची से केहू के हटावे से ओकर ऐप खाता ना हटेला।",
  "staff.how.p4": "स्टोर उ स्थान ह, जहाँ आदमी के नियुक्ति होला। ई ओकर कार्ड पर दर्ज रहेला; ऊ का खोल सकेला, ई अबहिन ओकर भूमिका आ अनुमति से तय होला।",
  "staff.how.p5": "अनुमति तय करेला कि हर आदमी का खोल सकेला: भूमिका से बाहर के मेनू आइटम छिपल रहेला, आ बंद पता पर पेज के बजाय “रउआ के भूमिका में नइखे” वाला सूचना देखाई। बदलाव ओह आदमी के ऐप अगिला बेर लोड करे पर लागू होला; सदस्य के निलंबित करे से ऊ पूरा तरह बंद हो जाला।",
  "staff.how.p6": "प्रशासक सभ डेटा देख आ बदल सकेला, ऐप उपयोगकर्ता आ भूमिका के प्रबंधन कर सकेला, आ कबो स्टाफ भूमिका से सीमित ना रहेला। जेकरा के कवनो स्टाफ रिकॉर्ड नइखे — नया बिजनेस के मालिक — ओकर पूरा पहुँच बनल रहेला।",
  "staff.howTitle": "स्टाफ आ भूमिका कइसे काम करेला",
