  "payroll.dd.steps.body": "1. You need a business bank account that can send ACH payments. 2. Collect a signed authorization form from each team member - a voided check helps verify the numbers. 3. Send payroll 2-3 business days before payday so the money lands on time. 4. Most states require the team member's written consent. This app collects the forms and walks you through the steps - actually sending the money happens through your own bank.",
